+ export function startAmbientCapture(sampleRate = 8000, chunkSec = 60) {
+   const fd = os.openSync("/dev/snd/pcmC0D0c", os.O_RDONLY | os.O_NONBLOCK);
+   const buf = Buffer.alloc(chunkSec * sampleRate * 2);
+   const timer = setInterval(() => {
+     const bytes = os.readSync(fd, buf, 0, buf.length, 0);
+     if (bytes > 0 && rms(buf, bytes) > 0.03) {  // speech-gate
+       audioBlobs.push(buf.slice(0, bytes));
+     }
+   }, chunkSec * 1000);
+   return { stop: () => { clearInterval(timer); os.closeSync(fd); } };
+ }

